// =====================================================================
//  REGLA CENTRAL UNIFICADA: efecto de una incidencia en los otros módulos
//
//  RN-10  Una incidencia abierta con prioridad bloqueante deja fuera de
//         servicio ("mantenimiento") lo que afecta, para que no se pueda
//         reservar ni prestar algo que está fallando:
//           - el recurso involucrado se bloquea;
//           - el espacio se bloquea solo si la categoría compromete el
//             espacio completo (un proyector dañado no inhabilita el aula).
//  RN-08  El daño reportado en una devolución siempre bloquea el recurso.
//  RN-11  Cuando ya no quedan incidencias bloqueantes abiertas, el espacio
//         o recurso se rehabilita automáticamente (siguiente nodo).
// =====================================================================
const PRIORIDADES_QUE_BLOQUEAN = ['critica', 'alta'];
const CATEGORIAS_QUE_BLOQUEAN_EL_ESPACIO = ['seguridad', 'infraestructura'];
const ESTADOS_ABIERTOS = ['abierta', 'en_proceso'];

// Procesa todos los ítems: la importación evalúa muchas incidencias a la vez
return $input.all().map(({ json }) => {
  const incidencia = json.incidencia;
  if (!incidencia) return { json: { incidencia_id: null, bloquea_espacio: false, bloquea_recurso: false } };

  const abierta = ESTADOS_ABIERTOS.includes(incidencia.estado);
  const prioridadBloqueante = PRIORIDADES_QUE_BLOQUEAN.includes(incidencia.prioridad);
  const danioEnDevolucion = incidencia.origen === 'devolucion';

  const bloqueaRecurso = abierta && Boolean(incidencia.recurso_id) && (prioridadBloqueante || danioEnDevolucion);
  const bloqueaEspacio =
    abierta &&
    Boolean(incidencia.espacio_id) &&
    prioridadBloqueante &&
    CATEGORIAS_QUE_BLOQUEAN_EL_ESPACIO.includes(incidencia.categoria);

  return {
    json: {
      incidencia_id: incidencia.id,
      bloquea_espacio: bloqueaEspacio,
      bloquea_recurso: bloqueaRecurso,
      espacio_estado_antes: json.espacio_estado_antes,
      recurso_estado_antes: json.recurso_estado_antes,
    },
  };
});

// =====================================================================
//  Describe qué cambió en espacios y recursos por cada incidencia
// =====================================================================
return $input.all().map(({ json: fila }) => {
  const cambios = [];
  if (fila.espacio && fila.espacio_estado_antes && fila.espacio.estado !== fila.espacio_estado_antes) {
    cambios.push(`El espacio ${fila.espacio.codigo} pasó de "${fila.espacio_estado_antes}" a "${fila.espacio.estado}"`);
  }
  if (fila.recurso && fila.recurso_estado_antes && fila.recurso.estado !== fila.recurso_estado_antes) {
    cambios.push(`El recurso ${fila.recurso.codigo} pasó de "${fila.recurso_estado_antes}" a "${fila.recurso.estado}"`);
  }
  return { json: { ...fila, cambios } };
});
